function validate([fruits, baskets]) {
  if (fruits.length < 1 || fruits.length > 100000) return 'fruits needs 1 to 100,000 values.';
  if (baskets.length !== fruits.length) return 'fruits and baskets have the same length.';
  if (fruits.some(v => v < 1 || v > 1e9) || baskets.some(v => v < 1 || v > 1e9)) return 'Every quantity and capacity is between 1 and 10^9.';
  return null;
}

