function numOfUnplacedFruits(fruits, baskets) {
  const n = baskets.length;
  let size = 1;
  while (size < n) {
    size *= 2;
  }
  const tree = new Array(2 * size).fill(0);
  for (let i = 0; i < n; i++) {
    tree[size + i] = baskets[i];
  }
  for (let node = size - 1; node >= 1; node--) {
    tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
  }
  let unplaced = 0;
  for (const fruit of fruits) {
    if (tree[1] < fruit) {
      unplaced++;
      continue;
    }
    let node = 1;
    while (node < size) {
      if (tree[2 * node] >= fruit) {
        node = 2 * node;
      } else {
        node = 2 * node + 1;
      }
    }
    tree[node] = 0;
    node = Math.floor(node / 2);
    while (node >= 1) {
      tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
      node = Math.floor(node / 2);
    }
  }
  return unplaced;
}

