function numOfUnplacedFruits(fruits, baskets) {
  // Simulate directly: scan the baskets from the left for each kind.
  const used = baskets.map(() => false);
  let unplaced = 0;
  for (const fruit of fruits) {
    let placed = false;
    for (let j = 0; j < baskets.length && !placed; j++) {
      if (!used[j] && baskets[j] >= fruit) {
        used[j] = true;
        placed = true;
      }
    }
    if (!placed) unplaced++;
  }
  return unplaced;
}

