function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(1, 8);
  // A narrow range makes ties and near misses; the full range checks big quantities.
  const top = rand() < 0.6 ? int(1, 10) : 1000000000;
  const fruits = Array.from({ length: n }, () => int(1, top));
  const baskets = Array.from({ length: n }, () => int(1, top));
  return [fruits, baskets];
}
